CREATE TABLE IF NOT EXISTS app_state (state_key TEXT PRIMARY KEY,state_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT,b5_id TEXT UNIQUE,referral_id TEXT,name TEXT,mobile TEXT UNIQUE,email TEXT,password_hash TEXT,status TEXT,place TEXT,photo TEXT,profile_locked INTEGER DEFAULT 0,current_level INTEGER DEFAULT 1,level_member_id TEXT,joined_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT UNIQUE,customer_id INTEGER,b5_id TEXT,mobile TEXT,order_json TEXT NOT NULL,status TEXT,created_at TEXT NOT NULL,updated_at TEXT,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE INDEX IF NOT EXISTS idx_customers_b5 ON customers(b5_id);CREATE INDEX IF NOT EXISTS idx_customers_mobile ON customers(mobile);CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id);CREATE INDEX IF NOT EXISTS idx_orders_b5 ON orders(b5_id);CREATE INDEX IF NOT EXISTS idx_orders_created ON orders(created_at);
